def grid_segment(cells):
    """Show a visual representation of cells"""
    height = max(r for r,c in cells) + 1 if cells else 0
    width = max(c for r,c in cells) + 1 if cells else 0
    grid = [[None]*width for _ in range(height)]
    for r,c in cells:
        grid[r][c] = '*'
    return "\n".join("".join(r if r else '.' for r in row) for row in grid)

