def build_4way_output(starting_8s, grid, height, width):
    visited = set()
    queue = deque(starting_8s)

    while queue:
        r, c = queue.popleft()
        if (r,c) in visited:
            continue
        visited.add((r,c))

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < height and 0 <= nc < width:
                if grid[nr][nc] != 3 and (nr,nc) not in visited:
                    queue.append((nr, nc))

    output = []
    for r in range(height):
        row = []
        for c in range(width):
            if (r,c) in visited:
                row.append(8)
            elif grid[r][c] == 3:
                row.append(3)
            else:
                row.append(grid[r][c])
        output.append(row)
    return visited, output

